scwin.gridView1_oncellclick = function(row, col) {
    if (col == 0) {
        var val = dataList1.getCellData(row, "chk");
        var r_idx = gridView1.getRealRowIndex(row);
        if (val == "1") {
            dataList1.deleteRow(r_idx);
        } else {
            dataList1.undeleteRow(r_idx);
        }
    }
};
scwin.__hasClass = function() {
    var el0 = WebSquare.wUnit.getJq("#gridView1_body_tbody tr")[0].childNodes[0];
    var el1 = WebSquare.wUnit.getJq("#gridView1_body_tbody tr")[1].childNodes[0];
    var el2 = WebSquare.wUnit.getJq("#gridView1_body_tbody tr")[2].childNodes[0];
    var el3 = WebSquare.wUnit.getJq("#gridView1_body_tbody tr")[3].childNodes[0];
    return WebSquare.wUnit.getJq(el0).hasClass("w2grid_rowStatus_D") && WebSquare.wUnit.getJq(el1).hasClass("w2grid_rowStatus_D") && WebSquare.wUnit.getJq(el2).hasClass("w2grid_rowStatus_D") && WebSquare.wUnit.getJq(el3).hasClass("w2grid_rowStatus_D");
}
scwin.__notHasClass = function() {
    var el0 = WebSquare.wUnit.getJq("#gridView1_body_tbody tr")[0].childNodes[0];
    var el1 = WebSquare.wUnit.getJq("#gridView1_body_tbody tr")[1].childNodes[0];
    var el2 = WebSquare.wUnit.getJq("#gridView1_body_tbody tr")[2].childNodes[0];
    var el3 = WebSquare.wUnit.getJq("#gridView1_body_tbody tr")[3].childNodes[0];
    return (!WebSquare.wUnit.getJq(el0).hasClass("w2grid_rowStatus_D")) && (!WebSquare.wUnit.getJq(el1).hasClass("w2grid_rowStatus_D")) && (!WebSquare.wUnit.getJq(el2).hasClass("w2grid_rowStatus_D")) && (!WebSquare.wUnit.getJq(el3).hasClass("w2grid_rowStatus_D"));
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 샘플파일 실행 후 첫번째 row를 체크한다.
    //1. Check the first row after executing the sample file.
    //Verify step 1. The child nodes are checked.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'gridView1_cell_0_0').getElementsByTagName('input')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_cell_0_0 input:checked').length == 1", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.__hasClass()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 첫번째 row를 체크해제한다.
    //2. Uncheck the first row.
    //Verify step 2. It is unchecked down to the child node (previously, only the first node is unchecked and the three child nodes remain checked)
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'gridView1_cell_0_0').getElementsByTagName('input')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.__notHasClass()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.init();
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 21-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
